/**
 * @brief Returns a+b when treated as F_2 vectors.
 * Needs them to be ordered.
 * 
 */


/**
 * @brief Returns a+b when treated as F_2 vectors.
 * Needs them to be ordered in reverse.
 * 
 */
template <typename index>
vec<index> legacy_rev_add(vec<index>& a, vec<index>& b) {
    vec<index> c;
    auto a_it = a.begin();
    auto b_it = b.begin();
    while(a_it != a.end() || b_it != b.end()) {
        if(a_it==a.end()) {
            c.push_back(*b_it);
            b_it++;
            continue;
        }
        if(b_it == b.end()) {
            c.push_back(*a_it);
            a_it++;
            continue;
        }
        if(*a_it > *b_it) {
            c.push_back(*a_it);
            a_it++;
        } else if(*a_it < *b_it) {
            c.push_back(*b_it);
            b_it++;
        } else { // *a_it==*b_it
            a_it++;
            b_it++;
        }      
    }
    return c;
}

/**
* @brief sparse column addition over F_2 for vectors whose entries are stored in reverse order. 
*/
template <typename index>
void legacy_rev_add_to(vec<index>& a, vec<index>& b) {
    b = legacy_rev_add(a, b);
}

template <typename index>
struct legacy_Column_traits<vec<index>, index> {

    template<class Range>
    static void legacy_add_to(const Range& v, vec<index>& w) {
        vec<index> result;
        std::set_symmetric_difference(v.begin(), v.end(), w.begin(), w.end(),
                                    std::back_inserter(result));
        w = std::move(result);
    }

    static bool is_nonzero_at(const vec<index>& v, index i) {
        return std::binary_search(v.begin(), v.end(), i);
    }

    static index last_entry_index(const vec<index>& v) {
        if(v.size() == 0) {
            return -1;
        } else {
            return v.back();
        }
    }


    template<class Left, class Right>
    static bool scalar_product(const Left& v, const Right& w){
        auto it_v = v.begin();
        auto it_w = w.begin();
        index count = 0;

        while (it_v != v.end() && it_w != w.end()) {
            if (*it_v < *it_w) {

                ++it_v;
            } else if (*it_w < *it_v) {

                ++it_w; 
            } else {

                ++it_v;
                ++it_w;
                count++;  
            }
        }
        return count % 2 != 0;
    }

    static void set_entry(vec<index>& v, index j) {
        if(last_entry_index(v) < j) {
            v.push_back(j);
        } else {
            auto it = std::lower_bound(v.begin(), v.end(), j);
            if(*it != j) {
                v.insert(it, j);
            } else {
                v.erase(it);
            }
        }  
    }

    static bool is_equal(const vec<index>& v, const vec<index>& w) {
        return v == w;
    }

    static bool is_zero(const vec<index>& v) {
        return v.empty();
    }

    static vec<index> get_standard_vector(index i, index n) {
        return vec<index>{i};
    }

    static vec<index> get_random_vector(index length, float rate) {
        vec<index> v;
        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
        auto& gen = legacy_get_rng();
        
        for(index i = 0; i < length; i++) {
            if(dist(gen) < rate) {
                v.push_back(i);
            }
        }
        return v;
    }


}; // Column_traits<vec<index>>
        


// Helper-functions for sets





template <typename index>
struct legacy_Column_traits<set<index>, index> {

    static void legacy_add_to(const set<index>& v, set<index>& w) {
        auto it_v = v.begin();
        auto it_w = w.begin();
    
        while (it_v != v.end() && it_w != w.end()) {
            if (*it_v < *it_w) {
                it_w = w.insert(it_w, *it_v);
                ++it_v;
            } else if (*it_w < *it_v) {
                ++it_w;
            } else {
                it_w = w.erase(it_w);
                ++it_v;
            }
        }
    
        w.insert(it_v, v.end());
    }

    static bool is_nonzero_at(const set<index>& v, index i) {
        return (v.find(i) != v.end());
    }

    static index last_entry_index(const set<index>& v) {
        if(v.size() == 0){
            return -1;
        } else {
            return *v.rbegin();
        }
    }

    static bool scalar_product(set<index>& v, set<index>& w) {
        //TO-DO: This isn't efficent, but it works for now.
        set<index> intersection;
        std::set_intersection(v.begin(), v.end(), w.begin(), w.end(), std::inserter(intersection, intersection.begin()));
        return intersection.size() % 2 == 1;
    }

    static void set_entry(set<index>& v, index j) {
        auto ins = v.insert(j);
        if(ins.second == false){
            v.erase(ins.first);
        }   
    }

    static bool is_equal(const set<index>& v, const set<index>& w) {
        return v == w;
    }

    static set<index> get_standard_vector(index i, index n) {
        return set<index>{i};
    }

    static set<index> get_random_vector(index length, float rate) {
        set<index> result;
        for(index i = 0; i < length; i++){
            if(static_cast<float>(rand()) / RAND_MAX < rate) {
                result.insert(result.end(), i);
            }
        }
        return result;
    }

    static set<index> get_zero_vector(index length) {
        return set<index>();
    }

}; // Column_traits<set<index>>

// Helper-functions for bitsets


template <typename index>
struct legacy_Column_traits<legacy_bitset, index> {

    static bool is_zero(const legacy_bitset& v) { return v.none(); }

    static void legacy_add_to(const legacy_bitset& v, legacy_bitset& w) {
        GRLINA_LEGACY_ASSERT(v.size() == w.size());
        w ^= v;
    }

    static bool is_nonzero_at(const legacy_bitset& v, index i) {
        return v[i];
    }

    static index last_entry_index(const legacy_bitset& v) {
        for (int i = v.size() - 1; i >= 0; --i) {
            if (v[i]) {
                return i;
            }
        }
        return -1;
    }

    static bool scalar_product(legacy_bitset& v, legacy_bitset& w) {
        return (v & w).count() % 2;
    }

    static void set_entry(legacy_bitset& v, index j) {
        v.flip(j);
    }

    static bool is_equal(const legacy_bitset& v, const legacy_bitset& w) {
        return v == w;
    }

    static legacy_bitset get_standard_vector(index i, index n) {
        return legacy_bitset(n, 0).set(i);
    }

    static legacy_bitset get_random_vector(index length, float rate) {
        legacy_bitset result(length, 0);
        for(index i = 0; i < length; i++) {
            if( static_cast<float>(rand()) / RAND_MAX < rate) {
                result.set(i);
            }
        }
        return result;
    }

    static legacy_bitset get_zero_vector(index length) {
        return legacy_bitset(length, 0);
    }

}; // Column_traits<bitset>

